lessons.example:
static String stats(int[] a) {
    int sum = 0, max = a[0], min = a[0];
    for (int x : a) {
        sum += x;
        if (x > max) max = x;
        if (x < min) min = x;
    }
    double avg = (double) sum / a.length;
    return "最高:" + max + " 最低:" + min + " 平均:" + avg;
}

