import java.util.*;

public class Main {
    static String topWord(String[] words) {
        Map<String,Integer> map = new HashMap<>();
        for (String w : words) {
            map.put(w, map.getOrDefault(w, 0) + 1);
        }
        String best = "";
        int max = 0;
        for (Map.Entry<String,Integer> e : map.entrySet()) {
            if (e.getValue() > max) {
                max = e.getValue();
                best = e.getKey();
            }
        }
        return best + ":" + max;
    }
}

