import java.util.*;

public class Main {
    public static void main(String[] args) {
        Bank b = new Bank();
        b.open("A", 100);
        b.open("B", 50);
        b.transfer("A", "B", 30);
        System.out.println(b.balance("A") + " " + b.balance("B"));
    }
}

class Account {
    String name;
    int balance;
    Account(String name, int balance) {
        this.name = name;
        this.balance = balance;
    }
}

class Bank {
    List<Account> accounts = new ArrayList<>();
    void open(String name, int money) {
        accounts.add(new Account(name, money));
    }
    Account find(String name) {
        for (Account a : accounts) {
            if (a.name.equals(name)) return a;
        }
        return null;
    }
    void deposit(String name, int money) {
        Account a = find(name);
        if (a != null && money > 0) a.balance += money;
    }
    void transfer(String from, String to, int money) {
        Account a = find(from);
        Account b = find(to);
        if (a == null || b == null || money <= 0 || a.balance < money) return;
        a.balance -= money;
        b.balance += money;
    }
    int balance(String name) {
        Account a = find(name);
        return a == null ? 0 : a.balance;
    }
}

