    }
}

class Task {
    String title;
    boolean done;
    Task(String title) {
        this.title = title;
    }
}

class TodoList {
    List<Task> tasks = new ArrayList<>();
    void add(String title) {
        tasks.add(new Task(title));
    }
    void done(int index) {
        tasks.get(index).done = true;
    }
    String render() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < tasks.size(); i++) {
            if (i > 0) sb.append("\n");
            Task t = tasks.get(i);
            sb.append(t.done ? "[x] " : "[ ] ").append(t.title);
        }
        return sb.toString();
    }
}

