lessons.solution:
public class Main {
    static boolean valid(String s) {
        char[] stack = new char[s.length()];
        int top = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(' || c == '[' || c == '{') stack[top++] = c;
            else {
                if (top == 0) return false;
                char open = stack[--top];
                if ((c == ')' && open != '(') || (c == ']' && open != '[') || (c == '}' && open != '{')) return false;
            }
        }
        return top == 0;
    }
}

