public class Main {
    static int maxProfit(int[] prices) {
        int min = Integer.MAX_VALUE;
        int best = 0;
        for (int p : prices) {
            if (p < min) min = p;
            else if (p - min > best) best = p - min;
        }
        return best;
    }
}

