public class Main {
    static void hanoi(int n, char from, char to, char helper) {
        if (n == 0) return;
        hanoi(n - 1, from, helper, to);
        System.out.println("move " + n + " " + from + "->" + to);
        hanoi(n - 1, helper, to, from);
    }
    public static void main(String[] args) {
        hanoi(3, 'A', 'C', 'B');
    }
}
